/****** Object:  StoredProcedure [Onwards].[AcceptResignation]    Script Date: 26-11-2025 14:58:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Onwards].[AcceptResignation]
	@Ids dbo.IntList READONLY,
	@LoginId INT
AS
BEGIN
	SET NOCOUNT ON;

	UPDATE Onwards.Resignation
	SET
		StatusId = 2,--Accepted
		IsActive = 0,
		ModifiedDate = GETDATE(),
		ModifiedBy = @LoginId
	WHERE UserId IN (SELECT Id FROM @Ids)

	UPDATE Onwards.Users
	SET 
		IsActive = 0,
		ModifiedDate = GETDATE(),
		ModifiedBy = @LoginId
	WHERE Id IN (SELECT Id FROM @Ids)
END
GO
