    BEGIN
        UPDATE Onwards.CertificationDetails
        SET
            Institute = @Institute,
            [Year] = @Year,
            ModifiedBy = @LoginId,
            ModifiedDate = GETDATE()
        WHERE Id = @ExistingId;
