CREATE PROCEDURE [Onwards].[SearchJobDetails]
    @SearchString VARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT * FROM Onwards.JobDetails
    WHERE (RolePurpose LIKE '%' + @SearchString + '%' OR DomainFunctionalSkills LIKE '%' + @SearchString + '%')
    AND IsActive = 1
    ORDER BY CreatedDate DESC;
END
